```javascript
const axios = require("axios");

async function getData(keyword) {
  try {
    const response = await axios.get(
      `https://cache.api.joox.com/openjoox/v3/search?country=id&lang=id&keyword=${encodeURIComponent(keyword)}`,
      {
        headers: {
          "Accept": "application/json, text/plain, */*"
        }
      }
    );

    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

getData("let me love you")
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
```
